ption value="ssl" <?=($cfg['imap_secure']??'ssl')==='ssl'?'selected':''?>>SSL/TLS</option><option value="tls" <?=($cfg['imap_secure']??'')==='tls'?'selected':''?>>STARTTLS</option><option value="none" <?=($cfg['imap_secure']??'')==='none'?'selected':''?>>Sin cifrado · no recomendado</option></select></div><div class="field"><label>Usuario IMAP</label><input name="imap_username" value="<?=htmlspecialchars($cfg['imap_username']??'')?>" placeholder="correo@dominio.com"></div><div class="field"><label>Contraseña / App Password</label><input name="imap_password" type="password" autocomplete="new-password" placeholder="<?=empty($cfg['imap_password'])?'Obligatoria':'•••••••• (conservar si queda vacío)'?>"></div><div class="field"><label>Carpeta</label><input name="imap_folder" value="<?=htmlspecialchars($cfg['imap_folder']??'INBOX')?>" placeholder="INBOX"></div></div><div class="graph-inbound-help notice info mail-info-note"><span class="mail-info-icon" aria-hidden="true"><i class="fa-brands fa-microsoft"></i></span><div><b>Recepción Microsoft Graph</b><span>Usa el mismo Tenant ID, Client ID, Client Secret y buzón configurados arriba. La aplicación de Azure debe tener permiso de aplicación <strong>Mail.Read</strong> con consentimiento de administrador.</span></div></div><div class="mail-inbound-status"><span class="status <?=($cfg['inbound_last_test_status']??'')==='ok'?'ok':(($cfg['inbound_last_test_status']??'')==='error'?'warning':'')?>"><?=htmlspecialchars(($cfg['inbound_last_test_status']??'')==='ok'?'Validado':(($cfg['inbound_last_test_status']??'')==='error'?'Requiere atención':'Sin probar'))?></span><small><?=htmlspecialchars($cfg['inbound_last_test_message']??'Guarda la configuración y luego prueba la recepción.')?></small></div><div class="actions-inline"><button class="primary" type="submit"><i class="fa-solid fa-floppy-disk"></i> Guardar recepción</button><button class="soft" type="button" id="testInboundMail"><i class="fa-solid fa-plug-circle-check"></i> Probar recepción</button></div></form></section>
