<script>document.addEventListener('DOMContentLoaded',()=>{const routes=document.getElementById('mailSenderRoutes');
let runRouteTest=null;
const mailRequest=async(fd)=>{const r=await fetch(location.href,{method:'POST',headers:{'X-ZYNKO-AJAX':'1'},body:fd});const j=await r.json();if(!j||typeof j.ok!=='boolean')throw new Error('Respuesta de correo inválida.');return j;};
if(routes){
 const cards=[...routes.querySelectorAll('.mail-route-card')];let busy=false;
 const getInput=card=>card.querySelector('input[type=email]');
 const paint=card=>{const field=getInput(card), status=card.querySelector('.mail-route-status'), value=field.value.trim(), saved=card.dataset.savedMailbox||'', current=value===saved, verified=current&&!!saved&&card.dataset.verified==='1';status.classList.toggle('ok',verified);status.querySelector('i').className='fa-solid '+(verified?'fa-circle-check':'fa-clock');status.querySelector('span').textContent=verified?'Remitente validado':(!current?(value?'Sin guardar · guarde y pruebe':'Cambio sin guardar'): (saved?'Pendiente de prueba':'Sin configurar · no se enviará'));};
 const lock=state=>{busy=state;routes.querySelectorAll('button,input[type=email]').forEach(el=>el.disabled=state);const main=document.getElementById('testConfiguredMail');if(main)main.disabled=state;};
 const requestBody=(action)=>{const fd=new FormData();fd.append('action',action);fd.append('csrf',routes.elements.csrf.value);return fd;};
 const updateSaved=(j,targets)=>{for(const card of targets){const row=j.data?.routes?.[card.dataset.purpose];card.dataset.savedMailbox=row?.mailbox||'';card.dataset.verified=row?.verified_at?'1':'0';getInput(card).value=card.dataset.savedMailbox;paint(card);}};
 const save=async(targets)=>{const fd=requestBody('email_sender_routes_save');if(targets.length===1)fd.append('only_purpose',targets[0].dataset.purpose);for(const card of targets){const field=getInput(card);if(!field.checkValidity()){throw new Error('Revise la dirección de correo de '+card.querySelector('label').textContent+'.');}fd.append('mailbox['+card.dataset.purpose+']',field.value.trim());}const j=await mailRequest(fd);if(!j.ok)throw new Error(j.message||'No se pudo guardar.');updateSaved(j,targets);return j;};
 const perform=async(targets,test=false,button=null)=>{if(busy)return;if(test&&!getInput(targets[0]).value.trim()){showNotify('error','Correo','Indique el buzón que desea probar.');return;}for(const card of targets){if(!getInput(card).reportValidity())return;}const text=button?.innerHTML;lock(true);if(button)button.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> '+(test?'Guardando y probando…':'Guardando…');try{const j=await save(targets);if(!test){showNotify('success','Correo',j.message);return;}const card=targets[0],fd=requestBody('email_test');fd.append('purpose',card.dataset.purpose);fd.append('expected_mailbox',card.dataset.savedMailbox);const result=await mailRequest(fd);if(!result.ok)throw new Error(result.message||'No se pudo probar el buzón.');const matches=String(result.data?.mailbox||'').toLowerCase()===card.dataset.savedMailbox.toLowerCase()&&result.data?.verified===true;card.dataset.verified=matches?'1':'0';paint(card);if(!matches){showNotify('error','Correo','El buzón cambió durante la prueba o no quedó validado. Vuelva a probarlo.');return;}showNotify('success','Remitente validado',result.data.mailbox+' · '+result.message);}catch(err){showNotify('error','Correo',err.message);}finally{lock(false);if(button)button.innerHTML=text;}};
 cards.forEach(card=>{const field=getInput(card);field.addEventListener('input',()=>paint(card));card.querySelector('.mail-route-save').addEventListener('click',e=>perform([card],false,e.currentTarget));card.querySelector('.mail-route-test').addEventListener('click',e=>perform([card],true,e.currentTarget));});
 document.getElementById('mailFillZynkoRoutes')?.addEventListener('click',()=>{const defaults={notifications:'notificaciones@zynkocloud.app',noreply:'noreply@zynkocloud.app',billing:'facturas@zynkocloud.app',support:'soporte@zynkocloud.app'};cards.forEach(card=>{const field=getInput(card);if(!field.value.trim()){field.value=defaults[card.dataset.purpose];paint(card);}});showNotify('info','Correo','Se completaron los campos vacíos. Guarde todos o use Guardar y probar.');});
 routes.addEventListener('submit',e=>{e.preventDefault();perform(cards,false,routes.querySelector('button[type=submit]'));});
 runRouteTest=()=>{const card=cards.find(c=>c.dataset.purpose==='notifications');if(card){card.scrollIntoView({behavior:'smooth',block:'center'});perform([card],true,card.querySelector('.mail-route-test'));}};
}
document.getElementById('testConfiguredMail')?.addEventListener('click',async()=>{const b=document.getElementById('testConfiguredMail'),old=b.innerHTML;const chosen=document.getElementById('mailMethod')?.value;const stored=<?=json_encode($method)?>;if(chosen!==stored){showNotify('info','Correo','Guarde primero el proveedor seleccionado.');return;}if(stored==='GRAPH'&&runRouteTest){runRouteTest();return;}b.disabled=true;b.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Enviando prueba…';try{const fd=new FormData();fd.append('action','email_test');const r=await fetch(location.href,{method:'POST',headers:{'X-ZYNKO-AJAX':'1'},body:fd});const j=await r.json();showNotify(j.ok?'success':'error',j.ok?'Correo verificado':'No se pudo enviar',j.message)}catch(e){showNotify('error','No se pudo enviar',e.message)}finally{b.disabled=false;b.innerHTML=old}});const m=document.getElementById('mailMethod'),ss=[...document.querySelectorAll('.smtp-fields')],gs=[...document.querySelectorAll('.graph-fields')];const sync=()=>{const graph=m.value==='GRAPH';ss.forEach(s=>{s.hidden=graph;s.querySelectorAll('input,select').forEach(e=>e.disabled=graph)});gs.forEach(g=>{g.hidden=!graph;g.querySelectorAll('input,select').forEach(e=>e.disabled=!graph)});};m.addEventListener('change',sync);if(window.jQuery)jQuery(m).on('change.mailProvider',sync);sync();const inbound=document.getElementById('inboundMethod'),imap=[...document.querySelectorAll('.imap-inbound-fields')],graphHelp=document.querySelector('.graph-inbound-help');const syncInbound=()=>{const v=inbound?.value||'NONE';imap.forEach(x=>x.hidden=v!=='IMAP');if(graphHelp)graphHelp.hidden=v!=='GRAPH'};inbound?.addEventListener('change',syncInbound);if(inbound&&window.jQuery)jQuery(inbound).on('change.mailInbound',syncInbound);syncInbound();document.getElementById('testInboundMail')?.addEventListener('click',async()=>{const b=document.getElementById('testInboundMail'),old=b.innerHTML;b.disabled=true;b.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Probando…';try{const fd=new FormData();fd.append('action','email_inbound_test');fd.append('csrf',document.getElementById('inboundMailConfigForm').elements.csrf.value);const r=await fetch(location.href,{method:'POST',headers:{'X-ZYNKO-AJAX':'1'},body:fd});const j=await r.json();showNotify(j.ok?'success':'error',j.ok?'Recepción validada':'Recepción no disponible',j.message);if(j.ok)setTimeout(()=>location.reload(),500)}catch(e){showNotify('error','No se pudo probar',e.message)}finally{b.disabled=false;b.innerHTML=old}});});</script>
